using System;
using System.Diagnostics;
public class WordLauncher {
    public static int Launch() {
        try {
            var psi = new ProcessStartInfo();
            psi.FileName = @\"C:\Program Files\Microsoft Office\root\Office16\WINWORD.EXE\";
