# 修复 CCleaner 对 WINWORD.EXE 的 IFEO 劫持
# 此脚本需要以管理员身份运行

$ifeaParent = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\WINWORD.EXE"
$subkeyName = "b6cf088aaed5f530_PD"
$subkeyPath = "$ifeaParent\$subkeyName"

Write-Host "=== 修复 Word IFEO CCleaner 劫持 ===" -ForegroundColor Cyan

# 1. 删除 CCleaner 注入的调试器子键
if (Test-Path $subkeyPath) {
    try {
        Remove-Item $subkeyPath -Force -Recurse
        Write-Host "[OK] 已删除 CCleaner 劫持子键: $subkeyName" -ForegroundColor Green
    } catch {
        Write-Host "[FAIL] 删除子键失败: $_" -ForegroundColor Red
    }
} else {
    Write-Host "[INFO] 子键不存在，已跳过" -ForegroundColor Yellow
}

# 2. 删除 UseFilter 和 MitigationOptions
foreach ($valueName in @("UseFilter", "MitigationOptions")) {
    try {
        Remove-ItemProperty $ifeaParent -Name $valueName -ErrorAction Stop
        Write-Host "[OK] 已删除: $valueName" -ForegroundColor Green
    } catch {
        Write-Host "[INFO] $valueName 不存在，已跳过" -ForegroundColor Yellow
    }
}

# 3. 如果父键为空，删除整个 IFEO\WINWORD.EXE 键
$remaining = (Get-Item $ifeaParent -ErrorAction SilentlyContinue).Property
$subkeys = (Get-ChildItem $ifeaParent -ErrorAction SilentlyContinue).Count
if (-not $remaining -and $subkeys -eq 0) {
    Remove-Item $ifeaParent -Force -ErrorAction SilentlyContinue
    Write-Host "[OK] 父键 IFEO\WINWORD.EXE 已完全清除" -ForegroundColor Green
} else {
    Write-Host "[INFO] 父键剩余内容: $remaining" -ForegroundColor Yellow
}

# 4. 同时将 HKLM Word 插件的 OfficePLUS 禁用
try {
    Set-ItemProperty "HKLM:\SOFTWARE\Microsoft\Office\Word\Addins\MSOfficePLUS" -Name LoadBehavior -Value 0 -ErrorAction Stop
    Write-Host "[OK] HKLM OfficePLUS 插件已禁用" -ForegroundColor Green
} catch {
    Write-Host "[INFO] HKLM OfficePLUS: $_" -ForegroundColor Yellow
}

Write-Host ""
Write-Host "=== 修复完成，现在测试 Word ===" -ForegroundColor Cyan
Start-Sleep -Seconds 1

$proc = Start-Process "C:\Program Files\Microsoft Office\root\Office16\WINWORD.EXE" -PassThru
Start-Sleep -Seconds 5
$proc.Refresh()
if (-not $proc.HasExited) {
    Write-Host "[SUCCESS] Word 正在运行！修复成功！" -ForegroundColor Green
} else {
    Write-Host "[FAIL] Word 仍退出，代码: $($proc.ExitCode)" -ForegroundColor Red
}

Write-Host ""
Write-Host "按任意键退出..."
$null = $Host.UI.RawUI.ReadKey("NoEcho,IncludeKeyDown")

